/**
 * Write `src/lib/tools/directory.generated.ts` from the tool catalogue.
 *
 *   pnpm tools:directory
 *
 * Run it after any change to a tool's slug, name, processing mode or accepted
 * formats. `src/lib/tools/directory.generated.test.ts` fails until you do: it
 * compares the generated file with a fresh projection of the catalogue. The
 * output is formatted with the repo's own Prettier config, so
 * `pnpm format:check` agrees with the file this writes. Same shape as
 * `pnpm guides:meta` (scripts/generate-guide-meta.ts).
 */
import { writeFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { format, resolveConfig } from "prettier";
import { tools } from "../src/lib/tools/catalog";
import { projectToolDirectory } from "../src/lib/tools/directory";

export const TOOL_DIRECTORY_FILE = path.join(
  process.cwd(),
  "src",
  "lib",
  "tools",
  "directory.generated.ts",
);

export async function writeToolDirectory(
  file = TOOL_DIRECTORY_FILE,
): Promise<number> {
  const entries = projectToolDirectory(tools);
  const source = [
    "// GENERATED by `pnpm tools:directory` (scripts/generate-tool-directory.ts)",
    "// from src/lib/tools/catalog.ts. Do not edit: directory.generated.test.ts",
    "// fails on any difference from a fresh projection of the catalogue.",
    'import type { ToolEntry } from "./directory";',
    "",
    `export const TOOL_DIRECTORY: readonly ToolEntry[] = ${JSON.stringify(entries, null, 2)};`,
    "",
  ].join("\n");
  const options = (await resolveConfig(file)) ?? {};
  writeFileSync(file, await format(source, { ...options, filepath: file }));
  return entries.length;
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) {
  writeToolDirectory().then(
    (count) => {
      process.stdout.write(
        `tools:directory: wrote ${count} tools to ${path.relative(process.cwd(), TOOL_DIRECTORY_FILE)}\n`,
      );
    },
    (error: unknown) => {
      process.stderr.write(`tools:directory: ${(error as Error).message}\n`);
      process.exit(1);
    },
  );
}
